      "Avant de nous aventurer à Tahou, nous devrons nous assurer que la ville n'est pas déjà tombée aux mains de Gnaag, pour ne pas nous jeter tête baissée dans un piège. J'ai de nombreux amis à Navasari, des amis sûrs qui occupent de hautes fonctions au Sénat d'Anarie.",
