      "Trois jours auparavant, à la frontière ouest, une bataille féroce a fait rage près de la ville de Lovka en Slovie, pour le contrôle du pont traversant le Churdas. Peu avant minuit, les forces réunies de la meute de Gnaag se sont abattues sur la garnison assiégée.",
      "Les soldats se sont vaillamment battus, mais à l'aube tout ce qui restait de la ville et de ses défenseurs se résumait à quelques hectares de terre brûlée, et à un tombereau rempli de restes humains carbonisés. Les trois armées ennemies avancent désormais sur Tahou.",
      "Le chef d'Etat, le Président Toltuda, a ordonné l'évacuation des femmes et des enfants de la capitale et a commencé à renforcer les défenses de la ville pour augmenter ses chances de résister au siège imminent. Lorsque Banedon annonce votre intention de vous rendre à Tahou, l'un de ses amis lui donne ce conseil : « Il ne serait pas sage de tenter un atterrissage dans la capitale.",
