      "« Le capitaine est encore en haut... halète-t-il d'une voix rauque. Il est monté pour sauver son frère juste avant que le feu prenne sur le toit. »",
      "Si vous maîtrisez la Discipline Magnakaï du Nexus et si vous avez atteint le rang de Maître Principal, rendez-vous au 159.",
